from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass, field
from enum import StrEnum

from ..formula import ParsedPrenexFormula
from ..parser import parse_quantified_formula


class BenchmarkDomain(StrEnum):
    CAD = "cad"
    QE = "qe"
    ROADMAP = "roadmap"
    COMPONENTS = "components"
    GROEBNER = "groebner"
    ROOTS = "roots"
    DECOMPOSITION = "decomposition"
    REGULAR_CHAINS = "regular_chains"
    SIGN = "sign"


@dataclass(frozen=True)
class Provenance:
    citation: str
    url: str = ""
    identifier: str = ""
    license: str = ""


@dataclass(frozen=True)
class Difficulty:
    variables: int
    max_degree: int | None = None
    polynomial_count: int | None = None
    quantifier_blocks: int = 0
    notes: str = ""


@dataclass(frozen=True)
class BenchmarkCase:
    name: str
    domain: BenchmarkDomain
    formula_text: str = ""
    description: str = ""
    variables: tuple[str, ...] = ()
    polynomials: tuple[str, ...] = ()
    tags: tuple[str, ...] = field(default_factory=tuple)
    provenance: Provenance | None = None
    difficulty: Difficulty | None = None
    expected: Mapping[str, object] = field(default_factory=dict)
    sample_points: tuple[Mapping[str, object], ...] = field(default_factory=tuple)
    expected_sample_truth: tuple[bool, ...] = field(default_factory=tuple)

    def parse(self) -> ParsedPrenexFormula:
        if not self.formula_text:
            raise ValueError(f"{self.name!r} is not a quantified-formula benchmark")
        return parse_quantified_formula(self.formula_text)


BATH_CAD_BANK = Provenance(
    citation="D. Wilson, Real Geometry and Connectedness via Triangular Description: CAD Example Bank",
    url="https://doi.org/10.15125/BATH-00069",
    identifier="CAD Example Bank v4",
    license="CC BY-SA 4.0",
)
GROEBNER_FAMILIES = Provenance(
    citation="Standard Cyclic, Katsura, ECO and Noon Gröbner benchmark families",
    url="https://github.com/mzinin/groebner_benchmarks",
    identifier="parameterized-groebner-families",
)
BPR = Provenance(
    citation="S. Basu, R. Pollack, M.-F. Roy, Algorithms in Real Algebraic Geometry, 2nd ed.",
    url="https://doi.org/10.1007/3-540-33099-2",
)


def cad_cases() -> tuple[BenchmarkCase, ...]:
    """Return the complete Wilson CAD Example Bank v4 corpus."""
    from .wilson_cad_bank import wilson_cad_cases

    return wilson_cad_cases()


def qe_cases() -> tuple[BenchmarkCase, ...]:
    """Return small established and textbook-style real QE problems."""
    return (
        BenchmarkCase(
            "positive_quadratic",
            BenchmarkDomain.QE,
            "forall x. x^2 + a*x + b > 0",
            variables=("x", "a", "b"),
            tags=("universal", "classical"),
            provenance=BPR,
            difficulty=Difficulty(3, 2, 1, 1),
            expected={"free_variables": ("a", "b")},
        ),
        BenchmarkCase(
            "parabola_projection",
            BenchmarkDomain.QE,
            "exists y. y^2 = x",
            variables=("y", "x"),
            tags=("existential", "projection"),
            provenance=BPR,
            difficulty=Difficulty(2, 2, 1, 1),
            expected={"sample_truth": {"x=1": True, "x=-1": False}},
        ),
        BenchmarkCase(
            "circle_projection",
            BenchmarkDomain.QE,
            "exists y. x^2 + y^2 = 1",
            variables=("y", "x"),
            tags=("existential", "equational-constraint"),
            provenance=BPR,
            difficulty=Difficulty(2, 2, 1, 1),
        ),
    )


def topology_cases() -> tuple[BenchmarkCase, ...]:
    """Return topology conformance cases with known component structure."""
    return (
        BenchmarkCase(
            "circle",
            BenchmarkDomain.ROADMAP,
            "x^2 + y^2 = 1",
            variables=("x", "y"),
            tags=("compact", "curve"),
            provenance=BPR,
            difficulty=Difficulty(2, 2, 1),
            expected={"components": 1, "dimension": 1},
        ),
        BenchmarkCase(
            "two_circles",
            BenchmarkDomain.COMPONENTS,
            "(x^2 + y^2 = 1) or ((x-3)^2 + y^2 = 1)",
            variables=("x", "y"),
            tags=("disconnected", "curves"),
            provenance=BPR,
            difficulty=Difficulty(2, 2, 2),
            expected={"components": 2, "dimension": 1},
        ),
        BenchmarkCase(
            "isolated_plus_circle",
            BenchmarkDomain.COMPONENTS,
            "(x^2 + y^2 = 1) or (x = 3 and y = 0)",
            variables=("x", "y"),
            tags=("mixed-dimension",),
            provenance=BPR,
            difficulty=Difficulty(2, 2, 3),
            expected={"components": 2},
        ),
    )


def _cyclic_case(n: int) -> BenchmarkCase:
    names = tuple(f"x{i}" for i in range(1, n + 1))
    polys = []
    for degree in range(1, n):
        terms = [
            "*".join(names[(start + offset) % n] for offset in range(degree)) for start in range(n)
        ]
        polys.append("+".join(terms))
    polys.append("*".join(names) + "-1")
    return BenchmarkCase(
        f"groebner_cyclic_{n}",
        BenchmarkDomain.GROEBNER,
        variables=names,
        polynomials=tuple(polys),
        tags=("cyclic", "literature", "parameterized"),
        provenance=GROEBNER_FAMILIES,
        difficulty=Difficulty(n, n, n),
    )


def _katsura_case(n: int) -> BenchmarkCase:
    names = tuple(f"u{i}" for i in range(n + 1))
    # Standard Katsura convolution equations, with the linear normalization.
    polys = ["u0+" + "+".join(f"2*u{i}" for i in range(1, n + 1)) + "-1"]
    for k in range(n + 1):
        terms = []
        for i in range(-n, n + 1):
            j = k - i
            if -n <= j <= n:
                terms.append(f"u{abs(i)}*u{abs(j)}")
        polys.append("+".join(terms) + f"-u{k}")
    return BenchmarkCase(
        f"katsura_{n}",
        BenchmarkDomain.GROEBNER,
        variables=names,
        polynomials=tuple(polys),
        tags=("katsura", "literature", "parameterized"),
        provenance=GROEBNER_FAMILIES,
        difficulty=Difficulty(n + 1, 2, len(polys)),
    )


def _eco_case(n: int) -> BenchmarkCase:
    names = tuple(f"x{i}" for i in range(1, n + 1))
    polys = ["+".join(names[:-1]) + "+1"]
    for i in range(1, n):
        terms = [f"x{i}*x{n}"]
        if i % 2:
            terms.append("1")
        terms.extend(f"x{j}*x{j + i}*x{n}" for j in range(1, n - i))
        polys.append("+".join(terms))
    return BenchmarkCase(
        f"eco_{n}",
        BenchmarkDomain.GROEBNER,
        variables=names,
        polynomials=tuple(polys),
        tags=("eco", "literature", "parameterized"),
        provenance=GROEBNER_FAMILIES,
        difficulty=Difficulty(n, 3, len(polys)),
    )


def _noon_case(n: int) -> BenchmarkCase:
    names = tuple(f"x{i}" for i in range(1, n + 1))
    polys = tuple(
        f"x{i}+" + "+".join(f"x{i}*x{j}" for j in range(1, n + 1) if j != i)
        for i in range(1, n + 1)
    )
    return BenchmarkCase(
        f"noon_{n}",
        BenchmarkDomain.GROEBNER,
        variables=names,
        polynomials=polys,
        tags=("noon", "literature", "parameterized"),
        provenance=GROEBNER_FAMILIES,
        difficulty=Difficulty(n, 2, n),
        expected={"reference_solution": "+".join(names)},
    )


def groebner_family(family: str, n: int) -> BenchmarkCase:
    """Construct a standard parameterized Gröbner benchmark case."""
    builders = {
        "cyclic": _cyclic_case,
        "katsura": _katsura_case,
        "eco": _eco_case,
        "noon": _noon_case,
    }
    try:
        builder = builders[family.lower()]
    except KeyError as exc:
        raise ValueError(f"unknown Gröbner benchmark family: {family!r}") from exc
    if n < 2:
        raise ValueError("benchmark size must be at least 2")
    return builder(n)


def algebraic_cases() -> tuple[BenchmarkCase, ...]:
    """Return representative sizes from established parameterized Gröbner families."""
    return tuple(
        groebner_family(family, n)
        for family, sizes in (
            ("cyclic", (3, 4, 5)),
            ("katsura", (3, 4, 5)),
            ("eco", (5, 6)),
            ("noon", (4, 5, 6)),
        )
        for n in sizes
    )


def all_cases() -> tuple[BenchmarkCase, ...]:
    return cad_cases() + qe_cases() + topology_cases() + algebraic_cases()


# Focused selectors retained because they describe benchmark semantics, not API history.
def literature_cases() -> tuple[BenchmarkCase, ...]:
    return tuple(case for case in all_cases() if "literature" in case.tags)


def nullification_cases() -> tuple[BenchmarkCase, ...]:
    return tuple(case for case in cad_cases() if "singular" in case.tags)


def eq_cons_cases() -> tuple[BenchmarkCase, ...]:
    return tuple(case for case in cad_cases() + qe_cases() if "equational-constraint" in case.tags)


def variable_ordering_cases() -> tuple[BenchmarkCase, ...]:
    return tuple(case for case in cad_cases() if "ordering" in case.tags)


def tticad_cases() -> tuple[BenchmarkCase, ...]:
    """Return the published 29-case TTICAD Section 8.2 dataset."""
    from .tticad_dataset import tticad_cases as _tticad_cases

    return _tticad_cases()


